import os
import time
import sys
from prefect import flow

# We will set the PREFECT_API_URL to point to the local server
os.environ["PREFECT_API_URL"] = "http://127.0.0.1:4200/api"

@flow(name="test-failure-flow")
def failure_flow():
    print("Running failure flow...")
    raise ValueError("This is a failure")

if __name__ == "__main__":
    try:
        failure_flow()
    except Exception as e:
        print(f"Caught exception: {e}")

import os
import time
from prefect import flow

os.environ["PREFECT_API_URL"] = "http://127.0.0.1:4200/api"

@flow(name="test-timeout-flow", timeout_seconds=5)
def timeout_flow():
    print("Running timeout flow...")
    for i in range(10):
        print(f"Sleeping {i}...")
        time.sleep(1)
    print("Finished timeout flow?")

if __name__ == "__main__":
    try:
        timeout_flow()
    except Exception as e:
        print(f"Caught exception: {type(e)}: {e}")

